const tsInput=document.getElementById("ts-input"),tsOutput=document.getElementById("ts-output");function updateCurrent(){const t=Date.now();document.getElementById("current-ts").textContent=Math.floor(t/1e3),document.getElementById("current-date").textContent=new Date().toLocaleString(i18n.currentLang==="ko"?"ko-KR":"en-US")}setInterval(updateCurrent,1e3),updateCurrent();function convertTs(){const t=tsInput.value.trim();if(!t)return tsOutput.textContent=i18n.t("common.enter_timestamp");let n=parseInt(t);if(isNaN(n))return tsOutput.textContent=i18n.t("common.enter_number");t.length<=10&&(n*=1e3);const o=new Date(n);if(isNaN(o.getTime()))return tsOutput.textContent=i18n.t("common.error_invalid_ts");const e=i18n.currentLang==="ko"?"ko-KR":"en-US",c=[`${i18n.t("common.ts_local")}: ${o.toLocaleString(e)}`,`${i18n.t("common.ts_utc")}: ${o.toUTCString()}`,`${i18n.t("common.ts_iso")}: ${o.toISOString()}`,"",`${i18n.t("common.ts_seconds")}: ${Math.floor(n/1e3)}`,`${i18n.t("common.ts_milliseconds")}: ${n}`];tsOutput.textContent=c.join(`
`),tsOutput.style.color="var(--text)"}function useNow(){tsInput.value=Math.floor(Date.now()/1e3),convertTs()}function downloadResult(){const t=tsOutput.textContent;if(!t||t===i18n.t("common.result_placeholder")||t.startsWith("\u274C"))return showToast(i18n.t("common.no_result"));downloadFile(t,"timestamp-result.txt")}function copyResult(){copyToClipboard(tsOutput.textContent).then(()=>showToast(i18n.t("common.copied")))}
